 * The page's "last updated" date and the records it was reviewed against.
 * tests/accessibility-statement.test.ts fails when the records change and this
 * is not reviewed again (DA1 (b)).
 */
export const STATEMENT_REVIEW = { date: "November 11, 2026", digest: "d2e1956c15bd55d1" } as const;

/**
 * Disputes on "Something not working?" (491 [PP2], unit 4; lib/checkup.ts
 * readDisputes, lib/checkup-rules.ts disputesCheck; added 1 November 2026).
 * Checked, with Stripe stubbed:
 *
 *   - read only, on the creator's own account, from the last 180 days, at
 *     most three pages of a hundred;
 *   - a dispute waiting for an answer is a problem, with the first due date
 *     and Stripe's own words for what happens unanswered;
 *   - none waiting is fine, saying how many are with the bank;
 *   - Stripe failing, slow or answering an odd shape is "not checked";
 *     more than three pages with none waiting is "not checked", and with
 *     some waiting says "at least";
 *   - with no Stripe account, the line is left out.
 */
import { CHECK_WAIT_MS, DISPUTE_DAYS, DISPUTE_PAGES, readDisputes, runCheckup } from "@/lib/checkup";
import { disputesCheck } from "@/lib/checkup-rules";
import { can } from "@/lib/team-roles";
import { done, is, part } from "./check";

const NOW = Date.UTC(2026, 10, 1, 12);
process.env.STRIPE_SECRET_KEY = "sk_test_checkup";
const DUE = Math.floor(Date.UTC(2026, 10, 8, 23, 59) / 1000);

type Page = { data: unknown; has_more: unknown } | "down" | "slow";
let pages: Page[] = [];
const asked: { method: string; url: string; account: string | null }[] = [];
globalThis.fetch = (async (input: string | URL | Request, init?: RequestInit) => {
  const url = String(input instanceof Request ? input.url : input);
  asked.push({ method: init?.method ?? "GET", url, account: new Headers(init?.headers).get("Stripe-Account") });
  if (url.includes("/v1/disputes")) {
    const page = pages.shift() ?? { data: [], has_more: false };
    if (page === "down") return new Response(JSON.stringify({ error: { message: "down" } }), { status: 500 });
    if (page === "slow") return new Promise<Response>(() => {});
    return new Response(JSON.stringify(page), { status: 200 });
  }
  return new Response(JSON.stringify({ configuration: { merchant: { capabilities: { card_payments: { status: "active" } } } }, requirements: { summary: { minimum_deadline: { status: "eventually_due" } } } }), { status: 200 });
}) as typeof fetch;

const ACCOUNT = "acct_1Disputesxxxxxx";
const d = (id: string, status: string, due: number | null = null, pastDue = false) => ({ id, status, evidence_details: { due_by: due, past_due: pastDue } });

async function main(): Promise<void> {
  part("Read only, on the creator's account");
  pages = [{ data: [d("du_1", "needs_response", DUE + 86_400), d("du_2", "warning_needs_response", DUE), d("du_3", "under_review"), d("du_4", "won")], has_more: false }];
  const read = await readDisputes(ACCOUNT, NOW);
  const call = asked.find((a) => a.url.includes("/v1/disputes"))!;
  is("a GET on the creator's own account, from the last 180 days", [call.method, call.account, call.url.includes(`created[gte]=${Math.floor(NOW / 1000) - DISPUTE_DAYS * 86_400}`), call.url.includes("limit=100")], ["GET", ACCOUNT, true, true]);
  const problem = disputesCheck(read, NOW);
  is("two waiting: a problem, with the next due date", [problem.state, problem.found], ["problem", "2 disputes are waiting for your answer on your Stripe account. The next is due on November 8 (UTC)."]);
  is("in Stripe's own words for an unanswered one", problem.ifLeft, "A dispute not answered by its due date is lost, and the disputed money cannot be won back.");
  is("where to answer, and the studio's page to look first", problem.fix?.kind === "outside" && problem.fix.where.includes("Disputes page of your Stripe Dashboard") && problem.fix.where.includes('the "Review one disputed purchase" page in your studio'), true);
  is("one waiting is said as one", disputesCheck({ disputes: [{ status: "needs_response", dueBy: DUE, pastDue: false }], complete: true }, NOW).found.startsWith("One dispute is waiting for your answer"), true);
  is("an appeal waiting for an answer is one too", disputesCheck({ disputes: [{ status: "appeal_needs_response", dueBy: DUE, pastDue: false }], complete: true }, NOW).state, "problem");
  const late = disputesCheck({ disputes: [{ status: "needs_response", dueBy: Math.floor(NOW / 1000) - 86_400, pastDue: true }, { status: "needs_response", dueBy: DUE, pastDue: false }], complete: true }, NOW);
  is("one past its due date: said, and never given as the next date", late.found, "2 disputes are waiting for your answer on your Stripe account. The next is due on November 8 (UTC). One is past its due date.");
  is("all past: no next date at all", disputesCheck({ disputes: [{ status: "needs_response", dueBy: Math.floor(NOW / 1000) - 60, pastDue: false }], complete: true }, NOW).found, "One dispute is waiting for your answer on your Stripe account. One is past its due date.");

  part("None waiting");
  const none = (status: string) => ({ status, dueBy: null, pastDue: false });
  is("some with the bank, an appeal among them: fine, counted", disputesCheck({ disputes: [none("under_review"), none("appeal_under_review"), none("lost"), none("warning_closed"), none("prevented")], complete: true }, NOW), { id: "disputes", title: "Disputes", state: "ok", found: "No dispute is waiting for your answer. 2 are with the buyer's bank for a decision." });
  is("none at all: fine", disputesCheck({ disputes: [], complete: true }, NOW).found, "No dispute is waiting for your answer on your Stripe account.");
  is("a status Stripe adds that this does not know: not checked, never fine", disputesCheck({ disputes: [none("something_new")], complete: true }, NOW).state, "not-checked");

  part("Unknown is never fine");
  pages = ["down"];
  is("Stripe failing: not checked", (await runCheckup({ sid: "a".repeat(32), listId: "b".repeat(32), statsId: "c".repeat(32), stripeAccountId: ACCOUNT, domain: null, subscriptionActive: true, tier: "pro", renewalUnpaidSince: 0, planDisputes: [] } as never, (p) => can("owner", p), NOW)).find((c) => c.id === "disputes")?.state, "not-checked");
  pages = ["slow"];
  const started = Date.now();
  is("Stripe not answering: not checked, on time", [disputesCheck(await readDisputes(ACCOUNT, NOW, 80).catch(() => null)).state, Date.now() - started < 2_000], ["not-checked", true]);
  pages = [{ data: "nope", has_more: false }];
  is("an odd answer: not checked", disputesCheck(await readDisputes(ACCOUNT, NOW).catch(() => null)).state, "not-checked");
  is("could not be read at all: not checked", disputesCheck(null).state, "not-checked");
  pages = [{ data: [null], has_more: false }];
  is("a row that is not a dispute: not checked", disputesCheck(await readDisputes(ACCOUNT, NOW).catch(() => null)).state, "not-checked");
  pages = [{ data: [{ status: "needs_response" }], has_more: false }];
  is("a dispute with no id: not checked", disputesCheck(await readDisputes(ACCOUNT, NOW).catch(() => null)).state, "not-checked");
  pages = [{ data: [d("du_a", "won")], has_more: true }, { data: [d("du_a", "won")], has_more: false }];
  is("the same dispute twice (a stuck cursor): not checked", disputesCheck(await readDisputes(ACCOUNT, NOW).catch(() => null)).state, "not-checked");
  pages = [{ data: [d("du_w", "needs_response", DUE)], has_more: true }, "slow"];
  const halfStart = Date.now();
  const half = await readDisputes(ACCOUNT, NOW, 400);
  is("the first page read, the second out of time: what was read is kept, said as at least", [half.complete, disputesCheck(half, NOW).found.startsWith("At least one dispute is waiting"), Date.now() - halfStart < 2_000], [false, true, true]);
  pages = [{ data: [d("du_x", "won")], has_more: true }, "down"];
  is("the second page failing, none waiting: not checked", disputesCheck(await readDisputes(ACCOUNT, NOW)).state, "not-checked");

  part("At most three pages");
  pages = Array.from({ length: DISPUTE_PAGES }, (_, i) => ({ data: [d(`du_p${i}`, "won")], has_more: true }));
  const many = await readDisputes(ACCOUNT, NOW);
  is("three pages read, then it stops", [DISPUTE_PAGES, many.complete, many.disputes.length], [3, false, 3]);
  is("more than it reads, none waiting: not checked, never fine", disputesCheck(many).state, "not-checked");
  is("more than it reads, some waiting: at least", disputesCheck({ disputes: [{ status: "needs_response", dueBy: DUE, pastDue: false }], complete: false }, NOW).found.startsWith("At least one dispute is waiting"), true);
  is("the next page starts after the last one read", asked.some((a) => a.url.includes("starting_after=du_p1")), true);

  part("No Stripe account");
  pages = [];
  is("left out: the payments line already says nothing can be sold", (await runCheckup({ sid: "a".repeat(32), listId: "b".repeat(32), statsId: "c".repeat(32), stripeAccountId: null, domain: null, subscriptionActive: true, tier: "pro", renewalUnpaidSince: 0, planDisputes: [] } as never, (p) => can("owner", p), NOW)).some((c) => c.id === "disputes"), false);
  is("each reader waits at most CHECK_WAIT_MS", CHECK_WAIT_MS, 8_000);
  done();
}

void main();

/**
 * CX-123 rules 24 and 30, lists from Stripe, lot 1 (money; C4-20261106-0105-C5-13):
 * a list read in another shape, or read only in part, is never taken for an
 * empty one. A "yes" may come from any readable row; a "no", a "none" or a
 * "zero" only from a list read to its end with every row readable
 * (lib/stripe-list.ts). Each point, against a stand-in for Stripe:
 *
 *   - plan disputes (lib/plan-disputes.ts): a page in another shape, or a row
 *     not readable, never marks the run complete;
 *   - plan refunds (lib/plan-refund-write.ts): a charge's refunds read in
 *     another shape, or with a row not readable, make no refund;
 *   - the Store assistant add-on (lib/assistant-billing.ts): whether a payment
 *     was disputed is not known from a page in another shape, so nothing is
 *     written on it this run; a dispute on a readable row still ends it;
 *   - an offer after paying (lib/upsell.ts): its charge is "not there" only
 *     when the customer's payments were read whole; one on a later page is found;
 *   - running memberships (lib/payment-methods.ts): never "none" from a page
 *     in another shape or a row not readable.
 */
import { syncPlanDisputes } from "@/lib/plan-disputes";
import { refundPlanPayment } from "@/lib/plan-refund-write";
import { syncAssistant } from "@/lib/assistant-billing";
import { OFFER_PAGES_IN_JOB, OFFER_PAGES_ON_PAGE, findOfferCharge, readUpsell, settlePendingOffers, settleUpsells } from "@/lib/upsell";
import { runningSubscriptions } from "@/lib/payment-methods";
import { STRIPE_LIST_VERSION, StripeListUnreadable, readStripePage } from "@/lib/stripe-list";
import { STRIPE_VERSION } from "@/lib/stripe-connect";
import { claimHandle, ensureStatsId, setAssistantPlan, setSubscription, storeForEmail, type Store } from "@/lib/store";
import { paidPeriod } from "./billing-period-fixture";
import { store as redis } from "./redis-stub";
import { done, is, part } from "./check";

process.env.STRIPE_SECRET_KEY = "sk_test_stripe_list_lot1_only";

type Handler = (method: string, path: string, query: URLSearchParams, init?: RequestInit) => Response | null;
let handler: Handler = () => null;
const sent: { method: string; path: string; version: string | null }[] = [];
globalThis.fetch = (async (input: string | URL | Request, init?: RequestInit) => {
  const url = new URL(String(input instanceof Request ? input.url : input));
  if (url.hostname !== "api.stripe.com") return new Response(null, { status: 404 });
  const method = init?.method ?? "GET";
  const path = url.pathname.replace(/^\/v1/, "");
  sent.push({ method, path, version: new Headers(init?.headers).get("stripe-version") });
  return handler(method, path, url.searchParams, init) ?? Response.json({ error: { message: `no stand-in for ${method} ${path}` } }, { status: 404 });
}) as typeof fetch;
const list = (data: unknown[], hasMore = false) => Response.json({ object: "list", data, has_more: hasMore });
/** Pages Stripe never gives: in another shape, as a proxy or a cache in the way could hand back. */
const GARBLED: [string, unknown][] = [
  ["no data", { object: "list", has_more: false }],
  ["data not a list", { object: "list", data: {}, has_more: false }],
  ["has_more missing", { object: "list", data: [] }],
  ["has_more as text", { object: "list", data: [], has_more: "false" }],
  ["not an object", []],
];

async function reader(): Promise<void> {
  part("The reader: a page in its exact shape, each row by its own fields");
  for (const [label, page] of GARBLED) {
    let thrown = "";
    try {
      readStripePage(page);
    } catch (error) {
      thrown = error instanceof StripeListUnreadable ? "unreadable" : String(error);
    }
    is(`${label}: not a page`, thrown, "unreadable");
  }
  const page = readStripePage({ data: [{ id: "sub_a1" }, "sub_b2", { id: 7 }, { id: "sub_c3", status: 1 }, { id: "sub_d4", status: "active" }], has_more: true }, (row) => typeof row.status === "string" || !("status" in row));
  is("readable rows kept, the others counted, never dropped silently", [page.rows.map((r) => r.id), page.unreadable, page.hasMore, page.lastId], [["sub_a1", "sub_d4"], 3, true, "sub_d4"]);
  const inherited = Object.create({ id: "sub_proto" });
  const getter = {};
  Object.defineProperty(getter, "id", { get: () => "sub_getter", enumerable: true });
  is("an inherited id or a getter is not readable", readStripePage({ data: [inherited, getter], has_more: false }).unreadable, 2);
  is("the next page starts only from a readable last row", readStripePage({ data: [{ id: "sub_a1" }, "x"], has_more: true }).lastId, null);
  is("the lot pins the version STRIPE_VERSION names", STRIPE_LIST_VERSION, STRIPE_VERSION);
}

async function disputes(): Promise<void> {
  part("plan-disputes.ts: a page in another shape or a row not readable never completes the run");
  for (const [label, page] of GARBLED) {
    redis.clear();
    handler = (method, path) => (method === "GET" && path === "/disputes" ? Response.json(page) : null);
    const counts = await syncPlanDisputes(Date.now() + 30_000);
    is(`disputes answered ${label}: not complete, a failure counted`, [counts.complete, counts.failed > 0], [false, true]);
  }
  redis.clear();
  handler = (method, path) => (method === "GET" && path === "/disputes" ? list(["dp_garbled"]) : null);
  const counts = await syncPlanDisputes(Date.now() + 30_000);
  is("a row not readable: counted as failed, not complete", [counts.complete, counts.failed], [false, 1]);
  redis.clear();
  handler = (method, path) => (method === "GET" && path === "/disputes" ? list([]) : null);
  is("a whole, readable empty list completes", (await syncPlanDisputes(Date.now() + 30_000)).complete, true);
}

async function planRefunds(): Promise<void> {
  part("plan-refund-write.ts: refunds read in another shape, or with a row not readable, make no refund");
  const DAY = 86_400;
  const NOW = Math.floor(Date.now() / 1000);
  let shop = 0;
  const made: string[] = [];
  const shopWith = async (refundsPage: unknown) => {
    shop += 1;
    const handle = `lotone${shop}`;
    const email = `${handle}@example.com`;
    const customer = `cus_${handle}01`;
    const sub = `sub_${handle}01`;
    const charge = `ch_${handle}x1`;
    await claimHandle(email, handle, `Lot ${shop}`, "");
    await setSubscription(email, { customerId: customer, subscriptionId: sub, active: true, tier: "creator", cycle: "month", trialEnds: 0 });
    const at = NOW - 3 * DAY;
    const invoice = { id: `in_${handle}x1`, subscription: sub, status: "paid", created: at, total: 6_900, tax: null, billing_reason: "subscription_create", charge, status_transitions: { paid_at: at }, lines: { data: [{ type: "subscription", period: { start: at }, price: { unit_amount: 6_900, currency: "usd", recurring: { interval: "month" } } }] } };
    const chargeRow = { id: charge, customer, invoice: invoice.id, payment_intent: `pi_${handle}x1`, status: "succeeded", paid: true, currency: "usd", created: at, amount_captured: 6_900, amount_refunded: 0, disputed: false, payment_method_details: { card: { fingerprint: `fp${handle}` } }, balance_transaction: { fee: 230, currency: "usd" } };
    handler = (method, path, q) => {
      if (method === "POST" && path === "/refunds") {
        made.push(handle);
        return Response.json({ id: `re_${handle}made`, object: "refund", amount: 6_900, currency: "usd", status: "succeeded" });
      }
      if (method !== "GET") return null;
      if (path === `/subscriptions/${sub}`) return Response.json({ id: sub, customer: { id: customer, email, balance: 0 }, metadata: { store: handle } });
      if (path === "/invoices") return list(q.get("subscription") === sub ? [invoice] : []);
      if (path === "/charges") return list(q.get("customer") === customer ? [chargeRow] : []);
      if (path === `/charges/${charge}`) return Response.json(chargeRow);
      if (path === "/charges/search" || path === "/customers/search") return Response.json({ object: "search_result", data: [], has_more: false });
      if (path === "/disputes") return list([]);
      if (path === "/refunds") return Response.json(refundsPage);
      return null;
    };
    return (await storeForEmail(email))!;
  };
  for (const [label, page] of [...GARBLED.filter(([l]) => l !== "has_more missing" && l !== "has_more as text"), ["a row not readable", { object: "list", data: ["re_garbled"], has_more: false }] as [string, unknown]]) {
    made.length = 0;
    const store = await shopWith(page);
    const result = await refundPlanPayment(store, NOW);
    is(`refunds answered ${label}: nothing made`, [result.ok, made.length], [false, 0]);
  }
  // Codex CX1 on #2759: a row is a refund only with a refund's own id; any other id is not readable, so no refund.
  for (const [label, id] of [["a subscription's id", "sub_CX1Wrong0001"], ["underscores only", "___"]]) {
    made.length = 0;
    const store = await shopWith({ object: "list", data: [{ id, object: "refund", status: "failed", amount: 6_900 }], has_more: false });
    const result = await refundPlanPayment(store, NOW);
    is(`a refund row with ${label} for id: not readable, nothing made`, [result.ok, made.length], [false, 0]);
  }
  made.length = 0;
  const fine = await shopWith({ object: "list", data: [], has_more: false });
  const fineResult = await refundPlanPayment(fine, NOW);
  is("refunds read whole and readable: the refund is made once", [fineResult.ok, made.length], [true, 1]);
}

