/**
 * The two words every test here is written with.
 *
 * Deliberately not a framework. A test that needs a runner installed is a
 * test that stops being run the first time an install breaks, and what these
 * are for is catching the things that only show up when the code is actually
 * executed — which is where every defect found while building this came from.
 */
let failures = 0;
let checks = 0;
/** Whether the file reached done(): only that ends it with 0. */
let reached = false;

// A file that stops before done(), on a promise that never settles, ends when the event loop empties, with code 0:
// it would pass in CI without a word (Claude 6, 9 November 2026). At its exit it fails instead, with a line that
// says so. A file that reached done(), or that already fails (a check, an error thrown), is left as it is.
process.once("exit", (code) => {
  if (reached || code !== 0) return;
  console.log(`\nThis test file ended without reaching done() (${checks} checks ran): counted as a failure.`);
  process.exitCode = 1;
});

/** Compares by value, prints the line, and remembers a failure. */
export function is(what: string, got: unknown, want: unknown): void {
  checks += 1;
  const ok = JSON.stringify(got) === JSON.stringify(want);
  if (ok) {
    console.log(`  ok    ${what}`);
    return;
  }
  failures += 1;
  console.log(`  FAIL  ${what}`);
  console.log(`        expected ${JSON.stringify(want)}`);
  console.log(`        got      ${JSON.stringify(got)}`);
}

/** A heading, so a run reads as sections rather than as one long list. */
export function part(name: string): void {
  console.log(`\n${name}`);
}

/** Ends the process with the right code: what makes this usable in CI. */
export function done(): void {
  reached = true;
  console.log(
    failures === 0
      ? `\n${checks} checks, all passing.`
      : `\n${checks} checks, ${failures} failing.`,
  );
  // Ends by its exit code, never process.exit(): Node 24 can deadlock inside process.exit() when a V8 background
  // task waits for a garbage collection only the main thread can run (nodejs/node#64560; 9 CI verify jobs hung
  // 48 min after "96 checks, all passing." on 6 November). A normal end tears the heap down first. Anything a test
  // leaves open still ends the run: the timer below does not hold the process, it only fires if something else does.
  process.exitCode = failures === 0 ? 0 : 1;
  setTimeout(() => process.exit(process.exitCode), 2_000).unref();
}

/**
 * Runs every *.test.ts in this folder.
 *
 * esbuild does the TypeScript, which is why it is a devDependency: these run
 * with `npm test` and nothing else installed. "@/lib/redis" is swapped for an
 * in-memory one, so a test exercises the real code against a store that
 * behaves like the one it was written for, without reaching anything real.
 */
import { readdirSync, mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";
import { checkClientBundles } from "./client-bundles.mjs";
import {testAliases,testEnvironment} from "./test-config.mjs";
import {runTestFiles,runBundle,TEST_FILE_TIMEOUT_MS} from "./test-runner.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "..");
const out = mkdtempSync(join(tmpdir(), "nimbus-tests-"));
let failed = 0;

try {
  const files = readdirSync(here).filter((f) => f.endsWith(".test.ts")).sort();
  if (!files.length) {
    console.log("No tests found.");
    process.exit(0);
  }
  failed = await runTestFiles({files, compileTimeoutMs: TEST_FILE_TIMEOUT_MS, compile: async file => {
    const bundle = join(out, `${file}.cjs`);
    await build({
      entryPoints: [join(here, file)],
      bundle: true,
      platform: "node",
      format: "cjs",
      outfile: bundle,
      logLevel: "error",
      alias: testAliases(file,root,here),
    });
    return bundle;
  }, run: async (file, bundle, next) => {
    console.log(`\n=== ${file} ===`);
    return runBundle(bundle, testEnvironment(process.env), process.execPath, {timeoutMs: TEST_FILE_TIMEOUT_MS, label: file, diagnose: () => `next compile ${next()}`});
  }});
} finally {
  rmSync(out, { recursive: true, force: true });
}

const clientBundles = await checkClientBundles(root);
console.log(`\nBrowser bundles: ${clientBundles.total - clientBundles.failed}/${clientBundles.total} passed.`);
for (const failure of clientBundles.failures) console.error(failure);
failed += clientBundles.failed;

// Ends by its exit code, like tests/check.ts done(): Node 24 can deadlock inside process.exit() (nodejs/node#64274).
// The unref'd timer only fires if something (an esbuild service, a stray handle) still holds the process.
if (failed) {
  console.log(`\n${failed} test file(s) failed.`);
  process.exitCode = 1;
} else {
  console.log("\nEverything passing.");
  process.exitCode = 0;
}
setTimeout(() => process.exit(process.exitCode), 5_000).unref();

/**
 * Guard for tests/check-exit.proof.ts: done() must end the file by its exit code, never by process.exit() directly,
 * because Node 24 can deadlock inside process.exit() (9 CI verify jobs hung 48 min on 6 November). The stress proof
 * shows 6 of 16 children hanging with process.exit() and 0 of 48 with the exit code, on Node 24.22.2.
 */
import { strict as assert } from "node:assert";
import { spawnSync } from "node:child_process";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { readFileSync } from "node:fs";
import { test } from "node:test";

const source = readFileSync("tests/check.ts", "utf8");
const body = source.slice(source.indexOf("export function done("));
const end = body.indexOf("\n}\n");
const done = body.slice(0, end);

test("done() sets the exit code and lets the process end by itself", () => {
  assert.match(done, /process\.exitCode = failures === 0 \? 0 : 1;/);
});

test("done() never calls process.exit() directly; only a timer that does not hold the process may", () => {
  const code = done.split("\n").filter((line) => !line.trim().startsWith("//") && !line.trim().startsWith("*"));
  const direct = code.filter((line) => line.includes("process.exit(") && !line.includes("setTimeout("));
  assert.deepEqual(direct, []);
  assert.match(done, /setTimeout\(\(\) => process\.exit\(process\.exitCode\), \d[\d_]*\)\.unref\(\);/);
});

test("the runner ends by its exit code too, never process.exit() after a failure", () => {
  const runner = readFileSync("tests/run.mjs", "utf8");
  const tail = runner.slice(runner.indexOf("failed += clientBundles.failed;"));
  assert.match(tail, /process\.exitCode = 1;/);
  const code = tail.split("\n").filter((line) => !line.trim().startsWith("//"));
  assert.deepEqual(code.filter((line) => line.includes("process.exit(") && !line.includes("setTimeout(")), []);
});

// Exercise the helper in real isolated children, including a test that silently
// stops before done(). No provider, network, production setting or real data.
const helperUrl = pathToFileURL(resolve("tests/check.ts")).href;
function helperChild(program: string) {
  const child = spawnSync(process.execPath, [
    "--experimental-strip-types", "--input-type=module", "-e",
    "import(" + JSON.stringify(helperUrl) + ").then(check => {" + program + "});",
  ], { encoding: "utf8", timeout: 5_000 });
  assert.equal(child.error, undefined);
  assert.equal(child.signal, null);
  return child;
}

test("a successful completed synthetic test exits zero", () => {
  const child = helperChild('check.is("synthetic control", 1, 1); check.done();');
  assert.equal(child.status, 0);
  assert.match(child.stdout, /1 checks, all passing\./);
});

test("a failed synthetic assertion still exits nonzero", () => {
  const child = helperChild('check.is("synthetic mismatch", 1, 2); check.done();');
  assert.equal(child.status, 1);
  assert.match(child.stdout, /1 checks, 1 failing\./);
});

test("an unresolved synthetic test without done cannot silently pass", () => {
  const child = helperChild('check.is("synthetic first check", 1, 1); void new Promise(() => {});');
  assert.equal(child.status, 1);
  assert.match(child.stdout, /ended without reaching done\(\)/);
});

/**
 * Node 24 can deadlock inside process.exit(): the main thread waits for the V8 worker threads to stop while one
 * of them waits for a garbage collection only the main thread can run (CI verify hung for 48 min right after
 * "96 checks, all passing." in 9 jobs on 6 November; gdb: MainThread in NodePlatform::Shutdown/uv_thread_join,
 * V8Worker in CollectionBarrier::AwaitCollectionBackground; nodejs/node#64560). A test file must end by its exit
 * code, so the heap is torn down before the platform is.
 *
 * The proof runs children that allocate hard and then call done(), with V8's --stress-concurrent-allocation,
 * which makes that race frequent; with process.exit() about a third of them never end. Each child gets 15 s.
 *
 * Run it by hand on the CI's Node (24.x): node tests/run-one is not needed — bundle it like any test and run it.
 * It is a .proof.ts, not a .test.ts, so the suite does not run 16 stressed children on every verify, and on
 * Node 22 the stress flag hangs children even on a normal exit, so the proof is meaningful only on Node 24.
 */
import { spawn } from "node:child_process";
import { done, is, part } from "./check";

const CHILDREN = 16;
const AT_ONCE = 8;
const LIMIT_MS = 15_000;

function allocateThenDone(): void {
  const keep: unknown[] = [];
  const until = Date.now() + 300;
  while (Date.now() < until) {
    keep.push(new Array(2_000).fill(Math.random()));
    if (keep.length > 400) keep.splice(0, 200);
  }
  is("the child counted its one check", keep.length > 0, true);
  done();
}

function runChild(): Promise<"ended" | "hung"> {
  return new Promise((resolve) => {
    const child = spawn(process.execPath, ["--stress-concurrent-allocation", process.argv[1]], { env: { ...process.env, CHECK_EXIT_CHILD: "1" }, stdio: "ignore" });
    const timer = setTimeout(() => {
      child.kill("SIGKILL");
      resolve("hung");
    }, LIMIT_MS);
    child.once("exit", () => {
      clearTimeout(timer);
      resolve("ended");
    });
  });
}

async function main(): Promise<void> {
  part("A test file that has printed its result also ends (no deadlock inside process.exit)");
  const results: ("ended" | "hung")[] = [];
  for (let i = 0; i < CHILDREN; i += AT_ONCE) results.push(...(await Promise.all(Array.from({ length: Math.min(AT_ONCE, CHILDREN - i) }, runChild))));
  is(`all ${CHILDREN} children that allocate hard and call done() end within ${LIMIT_MS / 1000} s`, results.filter((r) => r === "hung").length, 0);
  done();
}

if (process.env.CHECK_EXIT_CHILD === "1") allocateThenDone();
else main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
